package Image::ExifTool::RSRC;use strict;use vars qw($VERSION);use Image::ExifTool qw(:DataAccess :Utils);$VERSION='1.10';sub ProcessRSRC($$);%Image::ExifTool::RSRC::Main=(GROUPS=>{2=>'Document' },PROCESS_PROC=>\&ProcessRSRC,NOTES=>q{
        Tags extracted from Mac OS resource files, DFONT files and "._" sidecar
